#include <stdexcept>
#include <cstddef>
#include <vector>

int transform_all(std::size_t n, bool should_throw) {
    std::vector<int> buffer(n);

    for (std::size_t i = 0; i < n; ++i) buffer[i] = static_cast<int>(i) * 2;

    if (should_throw) {
        throw std::runtime_error("work failed");
    }

    int total = 0;
    for (std::size_t i = 0; i < n; ++i) total += buffer[i];

    return total;
}
